/*
 * @brief: destroy page home
 */
void destroy_page_home(bk_lv_ui_t *bk_ui)
{
    if (bk_ui == NULL) {
        return;
    }
    
    if (bk_ui->home != NULL) {
        lv_obj_del(bk_ui->home);
        bk_ui->home = NULL;
    }
}